using System;
using System.IO;
using System.Windows.Input;

namespace RustPlusDesk.Services;

/// <summary>
/// Provides native grab (open hand) and grabbing (hand grab) pointers for map navigation,
/// using the official Chromium cursor assets with automatic fallback to standard system cursors.
/// </summary>
public static class MapCursors
{
    private static Cursor? _grab;
    private static Cursor? _grabbing;

    /// <summary>
    /// Native grab (open hand) pointer displayed when mouse is inside the canvas in navigation mode.
    /// </summary>
    public static Cursor Grab => _grab ??= LoadCursor(NativeGrabBase64, Cursors.Hand);

    /// <summary>
    /// Native grabbing (hand grab) pointer displayed while actively dragging and panning the map.
    /// </summary>
    public static Cursor Grabbing => _grabbing ??= LoadCursor(NativeGrabbingBase64, Cursors.Hand);

    private static Cursor LoadCursor(string base64, Cursor fallback)
    {
        try
        {
            byte[] bytes = Convert.FromBase64String(base64);
            using var ms = new MemoryStream(bytes);
            return new Cursor(ms);
        }
        catch
        {
            return fallback;
        }
    }

    private const string NativeGrabBase64 =
        "";

    private const string NativeGrabbingBase64 =
        "";
}
